<div class="application-core" data-system-map>
<svg viewBox="0 0 1448 1080" role="img" aria-labelledby="application-core-title application-core-description">
    <title id="application-core-title">Connected application architecture</title>
    <desc id="application-core-description">An animated application core connects user interfaces, integrations, automation, databases and external services.</desc>
    <defs>
