        <style>
            .map-title{font:700 23px Manrope,Arial,sans-serif;fill:var(--ac-label)}.map-item{font:600 18px Manrope,Arial,sans-serif;fill:var(--ac-label)}.map-small{font:600 12px "JetBrains Mono",monospace;letter-spacing:.08em;text-transform:uppercase;fill:var(--ac-meta)}
            .map-panel{fill:var(--ac-box);fill-opacity:.82;stroke:var(--ac-box-stroke);stroke-width:1.6}.map-rule{stroke:var(--ac-box-stroke);stroke-opacity:.42}.map-icon{fill:none;stroke:currentColor;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round}.map-blue{color:#60a5fa}.map-green{color:#4ade80}.map-gold{color:#facc15}.map-neutral{color:var(--ac-label)}
            .map-link{fill:none;stroke-width:3;stroke-linecap:round;stroke-linejoin:round}.map-link-blue{stroke:#3b82f6}.map-link-green{stroke:#4ade80}.map-link-gold{stroke:#facc15}.map-core-breathe{transform-origin:724px 502px;animation:map-breathe 4s ease-in-out infinite}.map-pulse{animation:map-pulse 2.2s ease-in-out infinite}
