    @foreach ([['link-users','#4ade80','glow-green','0s'],['link-integrations','#60a5fa','glow-blue','.7s'],['link-automation','#facc15','glow-gold','1.4s'],['link-data','#60a5fa','glow-blue','2.1s'],['link-external','#60a5fa','glow-blue','2.8s']] as [$path,$color,$filter,$begin])<circle class="map-moving" r="7" fill="{{ $color }}" filter="url(#{{ $filter }})"><animateMotion dur="2s" begin="{{ $begin }}" repeatCount="indefinite"><mpath href="#{{ $path }}"/></animateMotion></circle>@endforeach
